async function(__ctx) {
  var result = {title:'',author:'',publishTime:'',errorHint:'',contentText:'',contentHtml:'',imageUrls:[]};
  var isWeixin = location.hostname.indexOf('mp.weixin.qq.com') >= 0;
  if (isWeixin) {
    var pickFirst = function() { for (var i=0; i<arguments.length; i++) { var el = document.querySelector(arguments[i]); if (el) { var t = (el.textContent||'').replace(/\s+/g,' ').trim(); if (t && t !== 'Name cleared') return t; } } return ''; };
    result.title = pickFirst('#activity-name','#js_text_title','.rich_media_title');
    result.author = pickFirst('#js_name','.wx_follow_nickname','#profileBt .profile_nickname','.rich_media_meta_nickname');
    var ptEl = document.querySelector('#publish_time');
    var ptText = ptEl ? (ptEl.textContent||'').trim() : '';
    if (!ptText) { var html = document.documentElement.innerHTML; var m1 = html.match(/create_time\s*:\s*JsDecode\('([^']+)'\)/); var rawTs = m1 ? m1[1] : ''; if (!rawTs) { var m2 = html.match(/create_time\s*[:=]\s*(?:"([^"]+)"|'([^']+)'|([0-9A-Za-z]+))/); rawTs = m2 ? (m2[1]||m2[2]||m2[3]||'') : ''; } if (/^\d{10}$|^\d{13}$/.test(rawTs)) { var ts = parseInt(rawTs,10); var ms = rawTs.length===13 ? ts : ts*1000; var d = new Date(ms+28800000); var pad = function(n){ return String(n).padStart(2,'0'); }; ptText = d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1)+'-'+pad(d.getUTCDate())+' '+pad(d.getUTCHours())+':'+pad(d.getUTCMinutes())+':'+pad(d.getUTCSeconds()); } }
    result.publishTime = ptText;
    var bodyText = document.body ? (document.body.innerText||'').replace(/\s+/g,' ').trim() : '';
    var fullHtml = document.documentElement.innerHTML;
    if (bodyText.indexOf('完成验证后即可继续访问') >= 0 || bodyText.indexOf('去验证') >= 0) { result.errorHint = 'environment verification required'; return result; }
    if (fullHtml.indexOf('secitptpage/verify.html') >= 0 || fullHtml.indexOf('id="js_verify"') >= 0) { result.errorHint = 'environment verification required'; return result; }
    var contentEl = document.querySelector('#js_content');
    if (!contentEl) { result.errorHint = 'content not found'; return result; }
    contentEl.querySelectorAll('img').forEach(function(img){ var ds = img.getAttribute('data-src'); if (ds) img.setAttribute('src', ds); });
    ['script','style','.qr_code_pc','.reward_area','.video_iframe','mpvideosnap'].forEach(function(sel){ contentEl.querySelectorAll(sel).forEach(function(el){ el.remove(); }); });
    contentEl.querySelectorAll('img').forEach(function(img){ var es=img.getAttribute('src')||''; var ec=img.className||''; if (/emoji|wp-smiley/i.test(ec) || es.indexOf('/emoji/')>=0) { img.replaceWith(document.createTextNode(img.getAttribute('alt')||'')); } });
    var seen = {}; contentEl.querySelectorAll('img[src]').forEach(function(img){ var src = img.getAttribute('src'); if (src && !seen[src]) { seen[src] = true; result.imageUrls.push(src); } });
    result.contentHtml = contentEl.innerHTML;
    result.contentText = (contentEl.innerText||contentEl.textContent||'').replace(/\n{3,}/g,'\n\n').trim();
    return result;
  } else {
    var pick = function() { for (var i=0;i<arguments.length;i++){ var el=document.querySelector(arguments[i]); if(el){ var raw = el.tagName==='META' ? (el.getAttribute('content')||'') : (el.textContent||''); var t=raw.replace(/\s+/g,' ').trim(); if(t) return t; } } return ''; };
    result.title = pick('meta[property="og:title"]','meta[name="twitter:title"]','h1','.article-title','.entry-title') || (document.title||'').trim();
    result.author = pick('meta[name="author"]','meta[property="article:author"]','[rel="author"]','.author','.byline','.post-author','.author-name');
    var tEl = document.querySelector('meta[property="article:published_time"]') || document.querySelector('meta[name="pubdate"]') || document.querySelector('meta[itemprop="datePublished"]');
    if (tEl) { result.publishTime = (tEl.getAttribute('content')||'').trim(); }
    if (!result.publishTime) { var tt = document.querySelector('time[datetime]'); if (tt) { result.publishTime = (tt.getAttribute('datetime')||tt.textContent||'').trim(); } }
    var best=null, bestLen=0;
    var cands = document.querySelectorAll('article,[role="main"],main,.article-content,.post-content,.entry-content,.rich_text,.article,.post,.content,#content,#article,#main');
    cands.forEach(function(el){ var len=0; el.querySelectorAll('p').forEach(function(p){ len += (p.textContent||'').length; }); if (len>bestLen) { bestLen=len; best=el; } });
    if (!best || bestLen<150) { best = document.querySelector('article') || document.body; }
    if (!best) { result.errorHint = 'content not found'; return result; }
    var clone = best.cloneNode(true);
    clone.querySelectorAll('img').forEach(function(img){ var ds = img.getAttribute('data-src')||img.getAttribute('data-original')||img.getAttribute('data-lazy-src')||img.getAttribute('data-actualsrc'); if (ds) img.setAttribute('src', ds); });
    ['script','style','nav','header','footer','aside','noscript','iframe','form','button','.comment','.comments','.related','.sidebar','.share','.advertisement','.ad','.recommend'].forEach(function(sel){ try { var ns=clone.querySelectorAll(sel); for (var j=0;j<ns.length;j++){ ns[j].remove(); } } catch(e){} });
    clone.querySelectorAll('img').forEach(function(img){ var es=img.getAttribute('src')||''; var ec=img.className||''; if (/emoji|wp-smiley/i.test(ec) || es.indexOf('/emoji/')>=0) { img.replaceWith(document.createTextNode(img.getAttribute('alt')||'')); } });
    var seen2={}; clone.querySelectorAll('img[src]').forEach(function(img){ var src=img.getAttribute('src'); if (src && src.indexOf('data:')!==0 && !seen2[src]) { seen2[src]=true; result.imageUrls.push(src); } });
    result.contentHtml = clone.innerHTML;
    result.contentText = (clone.textContent||'').replace(/\n{3,}/g,'\n\n').trim();
    if (!result.contentHtml && !result.contentText) { result.errorHint = 'content not found'; }
    return result;
  }
}
